def solve(a,b):
    seens, s = set(), 0
    n1, n2 = bisect(HARMO_NUM, a), bisect(HARMO_NUM, b)
    for n in HARMO_NUM[n1:n2]:
        if n not in seens:
            grp = [x for x in HARMO_GROUPS[HARMO_RATIOS[n]] if a <= x < b]
            if len(grp) > 1:
                seens |= set(grp)
                s += grp[0]
    return s
