def rotateWord(w, alpha, dct, d):
    lst = []
    for i,c in enumerate(w.lower(), 1):
        transChar = alpha[ (dct[c] + i*d) % 26 ]
        if w[i-1].isupper(): transChar = transChar.upper()
        lst.append(transChar)
