            alpha.append(c)
    alpha = ''.join(alpha)
    dct   = {c:i for i,c in enumerate(alpha)}
    return re.sub(r'[a-zA-Z]+', lambda m: rotateWord(m.group(),alpha,dct,d), text)

def decode(text, key):
