#!/usr/bin/env python3
"""
Goldbach Partitions CLI

A command-line interface for finding all unique Goldbach partitions
of an even number n (2 < n < 32000).
"""

import math
import sys

def goldbach_partitions(n):
    """Return all unique Goldbach partitions of even n as formatted strings."""
    def is_prime(x):
        """Check if x is prime using trial division up to sqrt(x)."""
        for i in range(2, int(math.sqrt(x)) + 1):
            if x % i == 0:
                return False
        return True

    if n % 2:  # n is odd
        return []

    ret = []
    for first in range(2, n // 2 + 1):
        if is_prime(first):
            second = n - first
            if is_prime(second):
                ret.append(f'{first}+{second}')
    return ret


def main():
    """Parse command-line arguments and display Goldbach partitions."""
    if len(sys.argv) != 2:
        print("Usage: python goldbach.py <even_number>")
        print("Example: python goldbach.py 26")
        sys.exit(1)

    try:
        n = int(sys.argv[1])
    except ValueError:
        print(f"Error: '{sys.argv[1]}' is not a valid integer.")
        sys.exit(1)

    if not (2 < n < 32000):
        print("Error: n must be an integer between 3 and 31999.")
        sys.exit(1)

    if n % 2 != 0:
        print(f"Error: {n} is odd. Goldbach's conjecture applies to even numbers.")
        sys.exit(1)

    partitions = goldbach_partitions(n)

    if not partitions:
        print(f"No Goldbach partitions found for {n}.")
    else:
        print(f"Goldbach partitions of {n}:")
        for partition in partitions:
            print(f"  {partition}")


if __name__ == "__main__":
    main()
