def segments(m, arr):
    # Validate m
    if not isinstance(m, int):
        raise TypeError("m must be an integer")
    if m < 0:
        raise ValueError("m must be non-negative")

    # Validate arr
    if not isinstance(arr, list):
        raise TypeError("arr must be a list of tuples")

    for i, seg in enumerate(arr):
        if not isinstance(seg, (list, tuple)):
            raise TypeError(f"Segment at index {i} must be a list or tuple of two integers")
        if len(seg) != 2:
            raise ValueError(f"Segment at index {i} must contain exactly two integers")

        l, r = seg
        if not (isinstance(l, int) and isinstance(r, int)):
            raise TypeError(f"Segment at index {i} must contain integers")
        if l < 0 or r < 0:
            raise ValueError(f"Segment at index {i} contains negative coordinates")
        if l > r:
            raise ValueError(f"Segment at index {i} has left endpoint greater than right endpoint")
        if l > m or r > m:
            raise ValueError(f"Segment at index {i} exceeds the upper bound m={m}")

    return [i for i in range(m + 1) if not any(a <= i <= b for a, b in arr)]
