def get_char_count(s):
    # Count occurrences of each alphanumeric character (case-insensitive)
    char_counts = {}
    for char in s.lower():
        if char.isalnum():
            char_counts[char] = char_counts.get(char, 0) + 1

    # Group characters by their count
    grouped = {}
    for char, count in char_counts.items():
        if count in grouped:
            grouped[count].append(char)
        else:
            grouped[count] = [char]

    # Sort characters alphabetically within each group
    for count in grouped:
        grouped[count].sort()

    # Return empty hash case
    if not grouped:
        return {0: []}

    return grouped
