Here's a small command-line interface wrapping that solution:

```python
#!/usr/bin/env python3
import sys
from functools import cmp_to_key

def largest_arrangement(numbers):
    """Arrange a list of non-negative integers to form the largest possible number."""
    cmp = lambda a, b: int(f'{b}{a}') - int(f'{a}{b}')
    return int(''.join(str(i) for i in sorted(numbers, key=cmp_to_key(cmp))))

def parse_input(input_str):
    """Parse comma-separated or space-separated integers from a string."""
    # Try comma separation first, then space
    if ',' in input_str:
        parts = input_str.split(',')
    else:
        parts = input_str.split()

    numbers = []
    for part in parts:
        part = part.strip()
        if part:
            try:
                num = int(part)
                if num < 0:
                    raise ValueError(f"Negative number not allowed: {num}")
                numbers.append(num)
            except ValueError as e:
                if "Negative" in str(e):
                    raise
                raise ValueError(f"Invalid integer: '{part}'")

    if not numbers:
        raise ValueError("No valid integers provided")

    return numbers

def main():
    print("Largest Number Arrangement")
    print("Enter a list of non-negative integers (comma or space separated).")
    print("Type 'quit' to exit.\n")

    while True:
        try:
            user_input = input("Enter numbers: ").strip()

            if user_input.lower() in ('quit', 'exit', 'q'):
                print("Goodbye!")
                break

            if not user_input:
                continue

            numbers = parse_input(user_input)
            result = largest_arrangement(numbers)

            print(f"Input: {numbers}")
            print(f"Largest arrangement: {result}\n")

        except ValueError as e:
            print(f"Error: {e}\n")
        except KeyboardInterrupt:
            print("\nGoodbye!")
            break
        except Exception as e:
            print(f"Unexpected error: {e}\n")

if __name__ == "__main__":
    # Also support command-line arguments
    if len(sys.argv) > 1:
        try:
            input_str = ' '.join(sys.argv[1:])
            numbers = parse_input(input_str)
            result = largest_arrangement(numbers)
            print(result)
        except Exception as e:
            print(f"Error: {e}", file=sys.stderr)
            sys.exit(1)
    else:
        main()
